use std::fs::File;
use std::os::unix::io::AsRawFd;
fn main(){
  let path = std::env::args().nth(1).unwrap_or("/tmp".to_string());
  let file = File::open(&path).expect("open failed");
  println!("opened fd {}", file.as_raw_fd());
  unsafe {
    let ptr = libc::mmap(std::ptr::null_mut(), 4096, libc::PROT_READ, libc::MAP_PRIVATE, file.as_raw_fd(), 0);
    if ptr == libc::MAP_FAILED {
      let err = std::io::Error::last_os_error();
      println!("mmap failed: {} raw={:?}", err, err.raw_os_error());
    } else {
      println!("mmap ok ptr {:?}", ptr);
      libc::munmap(ptr, 4096);
    }
  }
}
