fn unescape_replace(s: &str) -> String {
    // Should handle \n \t \r \\ and $$ and $...
    // Actually sd's replacement unescaping: \n -> newline, \t -> tab, \r -> CR, \\ -> \
    // And other \x remain as \x? Let's see: \a remains \a (backslash + a)
    // So algorithm: scan, if backslash + n/t/r/\ => replace, else keep both?
    let mut res = String::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i=0;
    while i<chars.len() {
        if chars[i]=='\\' && i+1<chars.len() {
            let nxt = chars[i+1];
            match nxt {
                'n' => { res.push('\n'); i+=2; },
                't' => { res.push('\t'); i+=2; },
                'r' => { res.push('\r'); i+=2; },
                '\\' => { res.push('\\'); i+=2; },
                _ => {
                    // keep as is? For \a, we want \a literal
                    res.push('\\');
                    res.push(nxt);
                    i+=2;
                }
            }
        } else {
            res.push(chars[i]);
            i+=1;
        }
    }
    res
}

