use regex::RegexBuilder;

fn unescape_replace(s: &str) -> String {
    let mut res = String::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i=0;
    while i<chars.len() {
        if chars[i]=='\\' && i+1<chars.len() {
            let nxt = chars[i+1];
            match nxt {
                'n' => { res.push('\n'); i+=2; },
                't' => { res.push('\t'); i+=2; },
                'r' => { res.push('\r'); i+=2; },
                '\\' => { res.push('\\'); i+=2; },
                _ => {
                    res.push('\\');
                    res.push(nxt);
                    i+=2;
                }
            }
        } else {
            res.push(chars[i]);
            i+=1;
        }
    }
    res
}

fn build_regex(pattern: &str, flags: &str) -> regex::Regex {
    let mut case_insensitive = false;
    let mut multiline = true;
    let mut dotall = false;

    let last_s = flags.rfind('s');
    let last_w = flags.rfind('w');

    let mut last_case: Option<char> = None;
    for ch in flags.chars() {
        if ch == 'c' || ch == 'i' || ch == 'w' {
            last_case = Some(ch);
        }
    }
    if let Some(c) = last_case {
        case_insensitive = c == 'i';
    }

    let word = flags.contains('w');

    if flags.contains('s') {
        if !flags.contains('w') {
            dotall = true;
        } else {
            if let (Some(s_pos), Some(w_pos)) = (last_s, last_w) {
                dotall = s_pos > w_pos;
            } else {
                dotall = true;
            }
        }
    }

    if flags.contains('e') {
        multiline = false;
    } else if flags.contains('w') {
        multiline = false;
    } else if flags.contains('s') && !flags.contains('m') {
        multiline = false;
    } else {
        multiline = true;
    }

    let mut pat = pattern.to_string();
    if word {
        pat = format!(r"\b{}\b", pat);
    }

    let mut builder = RegexBuilder::new(&pat);
    builder.case_insensitive(case_insensitive);
    builder.multi_line(multiline);
    builder.dot_matches_new_line(dotall);
    builder.build().unwrap()
}

fn main(){
  // Test replacement
  let re = build_regex("foo", "");
  let rep = unescape_replace("bar");
