use clap::Parser;
use regex::bytes::{RegexBuilder, Regex};
use std::fs;
use std::io::{self, Read, Write};
use std::path::Path;

/// An intuitive find & replace CLI
#[derive(Parser, Debug)]
#[command(version, about)]
struct Args {
    /// Display changes in a human reviewable format (the specifics of the format are likely to change in the future)
    #[arg(short = 'p', long = "preview")]
    preview: bool,

    /// Treat FIND and REPLACE_WITH args as literal strings
    #[arg(short = 'F', long = "fixed-strings")]
    fixed_strings: bool,

    /// Limit the number of replacements that can occur per file. 0 indicates unlimited replacements
    #[arg(short = 'n', long = "max-replacements", default_value_t = 0, value_name = "LIMIT")]
    max_replacements: usize,

    /// Regex flags. May be combined (like `-f mc`).
    ///
    /// c - case-sensitive
    ///
    /// e - disable multi-line matching
    ///
    /// i - case-insensitive
    ///
    /// m - multi-line matching
    ///
    /// s - make `.` match newlines
    ///
    /// w - match full words only
    #[arg(short = 'f', long = "flags", value_name = "FLAGS")]
    flags: Option<String>,

    /// The regexp or string (if using `-F`) to search for
    #[arg(value_name = "FIND")]
    find: String,

    /// What to replace each match with. Unless in string mode, you may use captured values like $1, $2, etc
    #[arg(value_name = "REPLACE_WITH")]
    replace_with: String,

    /// The path to file(s). This is optional - sd can also read from STDIN.
    ///
    /// Note: sd modifies files in-place by default. See documentation for examples.
    #[arg(value_name = "FILES")]
    files: Vec<String>,
}

fn unescape_replace(s: &str) -> Vec<u8> {
    // Handles \n \t \r \\, others kept as \ + char
    let mut res: Vec<u8> = Vec::new();
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'\\' && i + 1 < bytes.len() {
            let nxt = bytes[i + 1];
            match nxt {
                b'n' => {
                    res.push(b'\n');
                    i += 2;
                }
                b't' => {
                    res.push(b'\t');
                    i += 2;
                }
                b'r' => {
                    res.push(b'\r');
                    i += 2;
                }
                b'\\' => {
                    res.push(b'\\');
                    i += 2;
                }
                _ => {
                    // Keep as is: \ + char
                    res.push(b'\\');
                    res.push(nxt);
                    i += 2;
                }
            }
        } else {
            res.push(bytes[i]);
            i += 1;
        }
    }
    res
}

fn parse_flags(flags_str: &str) -> (bool, bool, bool, bool) {
    // Returns (case_insensitive, multiline, dotall, word)
    // case_insensitive: true if insensitive
    // multiline: true if ON
    // dotall: true if ON
    // word: true if ON

    // case: last occurrence among c,i,w
    let mut last_case: Option<char> = None;
    for ch in flags_str.chars() {
        if ch == 'c' || ch == 'i' || ch == 'w' {
            last_case = Some(ch);
        }
    }
    let case_insensitive = match last_case {
        Some('i') => true,
        _ => false,
    };

    let word = flags_str.contains('w');

    // dotall: s present and (no w or last s > last w)
    let dotall = if flags_str.contains('s') {
        if !flags_str.contains('w') {
            true
        } else {
            let last_s = flags_str.rfind('s').unwrap();
            let last_w = flags_str.rfind('w').unwrap();
            last_s > last_w
        }
    } else {
        false
    };

    // multiline
    let multiline = if flags_str.contains('e') {
        false
    } else if flags_str.contains('w') {
        false
    } else if flags_str.contains('s') && !flags_str.contains('m') {
        false
    } else {
        true
    };

    (case_insensitive, multiline, dotall, word)
}

fn build_regex(pattern: &str, flags_str: &str, fixed: bool) -> Result<Regex, String> {
    let (case_insensitive, multiline, dotall, word) = parse_flags(flags_str);

    let pat_string: String = if fixed {
        // Escape literal for regex
        let escaped = regex::escape(pattern);
        if word {
            format!(r"\b{}\b", escaped)
        } else {
            escaped
        }
    } else {
        if word {
            format!(r"\b{}\b", pattern)
        } else {
            pattern.to_string()
        }
    };

    let mut builder = RegexBuilder::new(&pat_string);
    builder.case_insensitive(case_insensitive);
    builder.multi_line(multiline);
    builder.dot_matches_new_line(dotall);

    // For empty pattern, regex crate should work as empty

    match builder.build() {
        Ok(re) => Ok(re),
        Err(e) => Err(e.to_string()),
    }
}

// For fixed mode, we want literal replacement without $ expansion
// We will use regex with closure returning literal bytes

fn replace_fixed(re: &Regex, input: &[u8], replace: &[u8], limit: usize) -> Vec<u8> {
    if limit == 0 {
        // unlimited
        let mut result = Vec::new();
        let mut last_end = 0;
        for m in re.find_iter(input) {
            result.extend_from_slice(&input[last_end..m.start()]);
            result.extend_from_slice(replace);
            last_end = m.end();
        }
        result.extend_from_slice(&input[last_end..]);
        result
    } else {
        let mut result = Vec::new();
        let mut last_end = 0;
        let mut count = 0;
        for m in re.find_iter(input) {
            if count >= limit {
                break;
            }
            result.extend_from_slice(&input[last_end..m.start()]);
            result.extend_from_slice(replace);
            last_end = m.end();
            count += 1;
        }
        result.extend_from_slice(&input[last_end..]);
        result
    }
}

fn replace_regex(re: &Regex, input: &[u8], replace: &[u8], limit: usize) -> Vec<u8> {
    if limit == 0 {
        re.replace_all(input, replace).into_owned()
    } else {
        re.replacen(input, limit, replace).into_owned()
    }
}

fn main() {
    let args = Args::parse();

    let flags_str = args.flags.unwrap_or_default();

    // Validate files before processing
    if !args.files.is_empty() {
        for path_str in &args.files {
            if path_str == "-" {
                eprintln!("error: invalid path: -");
                std::process::exit(1);
            }
            let path = Path::new(path_str);
            // Check existence
            match fs::metadata(path) {
                Ok(meta) => {
                    if meta.is_dir() {
                        // Simulate mmap error for directory: No such device (os error 19)
                        // Create an io error with raw os error 19
                        let err = io::Error::from_raw_os_error(19);
                        eprintln!("error: {}", err);
                        std::process::exit(1);
                    }
                    // Try to open for reading to catch permission denied
                    match fs::File::open(path) {
                        Ok(_) => {}
                        Err(e) => {
                            if e.kind() == io::ErrorKind::NotFound {
                                eprintln!("error: invalid path: {}", path_str);
                                std::process::exit(1);
                            } else {
                                eprintln!("error: {}", e);
                                std::process::exit(1);
                            }
                        }
                    }
                }
                Err(e) => {
                    if e.kind() == io::ErrorKind::NotFound {
                        eprintln!("error: invalid path: {}", path_str);
                        std::process::exit(1);
                    } else {
                        eprintln!("error: {}", e);
                        std::process::exit(1);
                    }
                }
            }
        }
    }

    // Build regex
    let re = match build_regex(&args.find, &flags_str, args.fixed_strings) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("error: invalid regex {}", e);
            std::process::exit(1);
        }
    };

    let replace_bytes: Vec<u8> = if args.fixed_strings {
        // literal, no unescape
        args.replace_with.as_bytes().to_vec()
    } else {
        unescape_replace(&args.replace_with)
    };

    if args.files.is_empty() {
        // Read from stdin
        let mut input = Vec::new();
        io::stdin().read_to_end(&mut input).unwrap();

        let output = if args.fixed_strings {
            replace_fixed(&re, &input, &replace_bytes, args.max_replacements)
        } else {
            replace_regex(&re, &input, &replace_bytes, args.max_replacements)
        };

        // For stdin, preview flag just outputs transformed content (no header)
        // So same as non-preview

        let stdout = io::stdout();
        let mut handle = stdout.lock();
        handle.write_all(&output).unwrap();
    } else {
        // Process files
        let mut file_contents: Vec<(String, Vec<u8>, Vec<u8>)> = Vec::new(); // path, original, transformed

        for path_str in &args.files {
            let data = fs::read(path_str).unwrap_or_else(|e| {
                if e.kind() == io::ErrorKind::NotFound {
                    eprintln!("error: invalid path: {}", path_str);
                    std::process::exit(1);
                } else {
                    eprintln!("error: {}", e);
                    std::process::exit(1);
                }
            });

            let transformed = if args.fixed_strings {
                replace_fixed(&re, &data, &replace_bytes, args.max_replacements)
            } else {
                replace_regex(&re, &data, &replace_bytes, args.max_replacements)
            };

            file_contents.push((path_str.clone(), data, transformed));
        }

        if args.preview {
            if file_contents.len() == 1 {
                let (_, _, transformed) = &file_contents[0];
                let stdout = io::stdout();
                let mut handle = stdout.lock();
                handle.write_all(transformed).unwrap();
            } else {
                let stdout = io::stdout();
                let mut handle = stdout.lock();
                for (path_str, _, transformed) in file_contents {
                    // Header: ----- FILE <path> -----
                    let header = format!("----- FILE {} -----\n", path_str);
                    handle.write_all(header.as_bytes()).unwrap();
                    handle.write_all(&transformed).unwrap();
                }
            }
        } else {
            // In-place modification
            for (path_str, original, transformed) in file_contents {
                if original != transformed {
                    // Write back
                    if let Err(e) = fs::write(&path_str, &transformed) {
                        eprintln!("error: {}", e);
                        std::process::exit(1);
                    }
                } else {
                    // Even if unchanged, original sd still writes? No, it doesn't modify mtime if unchanged? Our earlier test: file with no match, after sd, content same and exit 0. Does it rewrite? It probably doesn't rewrite if unchanged, but rewriting same content is okay.
                    // To avoid unnecessary write, we check if changed.
                    // But for files with same content, we still want to not error.
                }
            }
        }
    }
}
