                handle.write_all(transformed).unwrap();
            } else {
                let stdout = io::stdout();
                let mut handle = stdout.lock();
                for (path_str, _, transformed) in file_contents {
                    let header = format!("----- FILE {} -----\n", path_str);
                    handle.write_all(header.as_bytes()).unwrap();
                    handle.write_all(&transformed).unwrap();
                }
            }
        } else {
            for (path_str, original, transformed) in file_contents {
                if original != transformed {
                    if let Err(e) = fs::write(&path_str, &transformed) {
                        eprintln!("error: {}", e);
                        std::process::exit(1);
                    }
                }
            }
        }
    }
}
